#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ScalarPlugin {
    pub name: String,
    pub has_fixtures_export: bool,
}

pub fn emit_playwright_scalar_fixtures_barrel(active_plugins: &[ScalarPlugin]) -> String {
    let active_plugin_names = active_plugins
        .iter()
        .map(|plugin| plugin.name.as_str())
        .collect::<Vec<_>>()
        .join(", ");

    let mut output = String::new();
    output.push_str(
        "// AUTO-GENERATED by `lazuli generate playwright --target=scalar-fixtures-barrel`. DO NOT EDIT.\n",
    );
    output.push_str(&format!(
        "// Active scalar plugins: {active_plugin_names}\n"
    ));
    output.push_str("// v1 placeholder — when plugins ship their `/fixtures` export, the\n");
    output.push_str("// commented imports populate.\n\n");

    for plugin in active_plugins {
        let alias = fixture_alias(&plugin.name);
        let comment = if plugin.has_fixtures_export {
            ""
        } else {
            "// "
        };

        output.push_str(&format!(
            "{comment}import {{ fixtures as {alias} }} from '{}/fixtures';\n",
            plugin.name
        ));
    }

    output.push_str("\nexport const fixtures = {\n");

    for plugin in active_plugins {
        let alias = fixture_alias(&plugin.name);
        let comment = if plugin.has_fixtures_export {
            ""
        } else {
            "// "
        };

        output.push_str(&format!("  {comment}...{alias},\n"));
    }

    output.push_str(
        "} as Record<string, { generate: () => string; example?: string; invalid?: () => string }>;\n",
    );
    output
}

fn fixture_alias(plugin_name: &str) -> String {
    let package_name = plugin_name.rsplit('/').next().unwrap_or(plugin_name);
    let mut alias = String::from("_");
    let mut uppercase_next = false;

    for ch in package_name.chars() {
        if ch.is_ascii_alphanumeric() {
            let is_first_alias_char = alias.len() == 1;
            let alias_char = if is_first_alias_char {
                ch.to_ascii_lowercase()
            } else if uppercase_next {
                ch.to_ascii_uppercase()
            } else {
                ch
            };

            alias.push(alias_char);
            uppercase_next = false;
        } else if alias.len() > 1 {
            uppercase_next = true;
        }
    }

    if alias == "_" {
        alias.push_str("fixtures");
    }

    alias
}

#[cfg(test)]
mod tests {
    use super::{ScalarPlugin, emit_playwright_scalar_fixtures_barrel};

    #[test]
    fn emits_fixture_exports_for_active_scalar_plugins() {
        let output = emit_playwright_scalar_fixtures_barrel(&[
            ScalarPlugin {
                name: "@lazuli/plugin-scalars-br".to_owned(),
                has_fixtures_export: true,
            },
            ScalarPlugin {
                name: "@lazuli/plugin-scalars-ar".to_owned(),
                has_fixtures_export: false,
            },
        ]);

        assert_eq!(
            output,
            concat!(
                "// AUTO-GENERATED by `lazuli generate playwright --target=scalar-fixtures-barrel`. DO NOT EDIT.\n",
                "// Active scalar plugins: @lazuli/plugin-scalars-br, @lazuli/plugin-scalars-ar\n",
                "// v1 placeholder — when plugins ship their `/fixtures` export, the\n",
                "// commented imports populate.\n",
                "\n",
                "import { fixtures as _scalarsBr } from '@lazuli/plugin-scalars-br/fixtures';\n",
                "// import { fixtures as _scalarsAr } from '@lazuli/plugin-scalars-ar/fixtures';\n",
                "\n",
                "export const fixtures = {\n",
                "  ..._scalarsBr,\n",
                "  // ..._scalarsAr,\n",
                "} as Record<string, { generate: () => string; example?: string; invalid?: () => string }>;\n"
            )
        );
    }
}
